#pragma once
inline nlohmann::json rendering118Proof(hb::gpu::Device& gpu,const std::string& fixture,const char* section="rendering118"){using namespace hb::gpu;std::ifstream input(fixture);const auto packets=nlohmann::json::parse(input).at(section);SceneRenderer r(gpu,64,64);SceneFrame f;f.clear={0,0,0,1};f.eye={0,0,1,1};f.screenEffects.emplace();auto& s=*f.screenEffects;s.eye=f.eye;s.forward={0,0,-1,0};s.inverseVP=identity;s.inverseVP[10]=-1;s.inverseVP[14]=1;s.pathEnvironment={0,0,0,65000};nlohmann::json proof;
 const auto stats=[](const auto& p){double sum=0,sum2=0;for(int y=16;y<48;y++)for(int x=16;x<48;x++){const double v=p[(y*64+x)*4];sum+=v;sum2+=v*v;}return std::array<double,2>{sum/1024,sum2/1024-std::pow(sum/1024,2)};};
 for(const auto& item:packets.items()){const auto& p=item.value();const auto data=p.at("data").get<std::vector<float>>();std::vector<std::uint8_t> bytes(data.size()*4);std::memcpy(bytes.data(),data.data(),bytes.size());auto world=r.createDataTexture(p.at("width"),p.at("height"),bytes,4,true);r.setGeometryScene(&world);s.rayPrograms=readRayPrograms(p.at("rayInfo").at("programs"));const auto& settings=p.at("settings");s.geometryInfo=settings.at("geometryInfo").get<std::array<float,4>>();s.geometryLimits=settings.at("geometryLimits").get<std::array<float,4>>();s.transport=settings.at("transport").get<std::array<float,4>>();s.pathQuality=settings.at("pathQuality").get<std::array<float,4>>();s.pathLens=settings.at("pathLens").get<std::array<float,4>>();s.pathOptions=settings.at("pathOptions").get<std::array<float,4>>();s.pathMap=settings.at("pathMap").get<std::array<float,4>>();s.pathCaustics={0,64,.35f,1};s.pathDenoise={0,3,32,.02f};s.pathFilter={0,1,0,0};s.path={1,8,64,0};s.eye=f.eye;SceneRenderer::Texture environment;
  if(!p.at("environmentPacket").is_null()){const auto& e=p.at("environmentPacket");const auto values=e.at("data").get<std::vector<float>>();std::vector<std::uint8_t> b(values.size()*4);std::memcpy(b.data(),values.data(),b.size());environment=r.createDataTexture(e.at("width"),e.at("height"),b,4,true);r.setPathEnvironment(&environment);}else r.setPathEnvironment(nullptr);
  const auto capture=[&](int samples){s.path[3]=0;s.path[2]=float(samples);for(int j=0;j<samples/4;j++){s.path[3]=float(j*4);r.begin(f);if(j<samples/4-1)r.finish();}return r.readPixels();};
  if(item.key()=="lens"){s.eye[3]=0;s.pathLens[0]=.05f;s.pathLens[1]=2;const auto raw=capture(4);const auto before=stats(raw);s.pathDenoise[0]=1;const auto spatial=capture(4);const auto after=stats(spatial);std::cerr<<"118 lens "<<nlohmann::json(before)<<" "<<nlohmann::json(after)<<std::endl;assert(before[1]>1&&after[1]<before[1]*.9);assert(std::abs(before[0]-after[0])<30);const auto spatialBytes=r.bloomTextureBytes();s.pathDenoise[0]=.25f;s.pathFilter[0]=.8f;s.path={1,8,8,0};r.begin(f);r.finish();assert(r.bloomTextureBytes()==spatialBytes+64*64*24);s.path[3]=4;r.begin(f);const auto temporal=r.readPixels();s.pathFilter[0]=0;s.path[3]=8;r.begin(f);const auto current=r.readPixels();int changed=0;for(std::size_t i=0;i<current.size();i++)if(std::abs(int(current[i])-int(temporal[i]))>1)++changed;assert(changed>0);assert(r.bloomTextureBytes()==spatialBytes);s.pathFilter[1]=0;assert(capture(4)==raw);s.pathFilter={.8f,1,0,0};s.pathLens[1]=.4f;const auto focused=capture(4);s.pathFilter[0]=0;assert(capture(4)==focused);int rejected=0;for(int i=0;i<5;i++){const auto saved=s.pathFilter;if(i==0)s.pathFilter[0]=1;if(i==1)s.pathFilter[1]=-1;if(i==2)s.pathFilter[2]=2;if(i==3)s.pathFilter[3]=1;if(i==4)s.pathFilter[0]=std::numeric_limits<float>::quiet_NaN();try{r.begin(f);}catch(const std::exception&){++rejected;}s.pathFilter=saved;}assert(rejected==5);proof[item.key()]={{"raw",before},{"spatial",after},{"temporalChangedChannels",changed},{"temporalBytes",64*64*24},{"disabledTemporalReleases",true},{"zeroLensIsRaw",true},{"focusResetHasNoStaleHistory",true},{"nativeGuards",rejected}};
  }else{const auto raw=capture(64);const int off=raw[(32*64+32)*4];s.pathCaustics[0]=1;const auto lit=capture(64);const int on=lit[(32*64+32)*4];s.pathCaustics[3]=.25f;const auto reduced=capture(64);const int weak=reduced[(32*64+32)*4];s.pathCaustics[3]=0;const auto zero=capture(64);std::cerr<<"118 "<<item.key()<<" "<<off<<" "<<on<<" weak="<<weak<<" "<<int(zero[(32*64+32)*4])<<std::endl;assert(raw==zero);if(item.key()=="direct")assert(raw==lit);else assert(on>weak+8);proof[item.key()]={{"off",off},{"on",on},{"weak",weak},{"zero",zero[(32*64+32)*4]},{"zeroExactRaw",true}};}r.setGeometryScene(nullptr);r.setPathEnvironment(nullptr);
 }f.screenEffects.reset();r.begin(f);assert(r.bloomTextureBytes()==0);proof["passed"]=true;proof["actualComputeShader"]=true;proof["disabledResourcesZero"]=true;return proof;}
